namespace YourApp.Models;

public class EquipmentItem
{
    public int Id { get; set; }
    public string Name { get; set; } = string.Empty;
    public string Location { get; set; } = string.Empty;
    public DateTime LastInspected { get; set; }
}

using YourApp.Models;

namespace YourApp.Services;

public class EquipmentService
{
    public async Task<List<EquipmentItem>> GetEquipmentAsync()
    {
        // Simulate network/database latency
        await Task.Delay(500);

        return new List<EquipmentItem>
        {
            new() { Id = 1, Name = "Forklift A",        Location = "Warehouse 1", LastInspected = new DateTime(2026, 5, 10) },
            new() { Id = 2, Name = "Conveyor Belt B",   Location = "Warehouse 2", LastInspected = new DateTime(2026, 4, 22) },
            new() { Id = 3, Name = "Pallet Jack C",     Location = "Dock 3",      LastInspected = new DateTime(2026, 6, 1)  },
            new() { Id = 4, Name = "Crane D",           Location = "Yard",        LastInspected = new DateTime(2026, 3, 15) },
            new() { Id = 5, Name = "Compressor E",      Location = "Mech Room",   LastInspected = new DateTime(2026, 6, 20) },
            new() { Id = 6, Name = "Drill Press F",     Location = "Shop Floor",  LastInspected = new DateTime(2026, 2, 28) },
            new() { Id = 7, Name = "Lathe G",           Location = "Shop Floor",  LastInspected = new DateTime(2026, 1, 12) },
        };
    }
}

@page "/inventory"
@rendermode InteractiveServer
@using YourApp.Models
@using YourApp.Services
@inject EquipmentService EquipmentSvc
@inject PersistentComponentState ApplicationState
@implements IDisposable

<h1>Equipment Inventory</h1>

@if (_items is null)
{
    <p><em>Loading inventory...</em></p>
}
else
{
    <table class="table">
        <thead>
            <tr>
                <th>Id</th>
                <th>Name</th>
                <th>Location</th>
                <th>Last Inspected</th>
            </tr>
        </thead>
        <tbody>
            @foreach (var item in _items)
            {
                <tr>
                    <td>@item.Id</td>
                    <td>@item.Name</td>
                    <td>@item.Location</td>
                    <td>@item.LastInspected.ToShortDateString()</td>
                </tr>
            }
        </tbody>
    </table>
}

@code {
    private List<EquipmentItem>? _items;
    private PersistingComponentStateSubscription _persistingSubscription;

    protected override async Task OnInitializedAsync()
    {
        _persistingSubscription = ApplicationState.RegisterOnPersisting(PersistData);

        // Try to restore data that was already fetched during prerender
        if (ApplicationState.TryTakeFromJson<List<EquipmentItem>>("inventory", out var restored))
        {
            _items = restored;
        }
        else
        {
            // First render (prerender) — actually call the service
            _items = await EquipmentSvc.GetEquipmentAsync();
        }
    }

    private Task PersistData()
    {
        ApplicationState.PersistAsJson("inventory", _items);
        return Task.CompletedTask;
    }

    public void Dispose()
    {
        _persistingSubscription.Dispose();
    }
}

